#[inline]
fn destack_io_poll_wait_replay(
    context: &RuntimeCallContext,
    out: *mut NativeArray<PollEvent>,
    handle: resource::PollHandle,
    timeoutns: u64,
    maxevents: u32,
) -> RuntimeResult<()> {
    let _ = (&handle, &timeoutns, &maxevents);

    context.replay().run_binding(
        POLL_WAIT,
        || unsafe {
            platform_native::destack_io_poll_wait(context, out, handle, timeoutns, maxevents)
        },
        |result| {
            if let Ok(()) = result {
                let result_value = unsafe {
                    if out.is_null() {
                        return Err(RuntimeError::from(PlatformError::null_pointer("out")).boxed());
                    }
                    *out
                };
                let result_replay_raw = unsafe { result_value.as_slice()? };
                let mut result_replay = Vec::with_capacity(result_replay_raw.len());
                for result_replay_item_value in result_replay_raw {
                    let result_replay_item = *result_replay_item_value;
                    let result_replay_item_replay_key = result_replay_item.key;
                    let result_replay_item_replay_ready = result_replay_item.ready;
                    let result_replay_item_replay_error = result_replay_item.error;
                    let result_replay_item_replay = PollEvent {
                        key: result_replay_item_replay_key,
                        ready: result_replay_item_replay_ready,
                        error: result_replay_item_replay_error,
                    };
                    result_replay.push(result_replay_item_replay);
                }
                let payload = PollWaitReplay {
                    result: Ok(result_replay),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(PlatformError::from(error.as_ref()));
                    PollWaitReplay { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |payload| {
            // replay result
            match payload.result {
                Ok(value) => {
                    let mut value_native_values = Vec::with_capacity(value.len());
                    for value_native_item in value {
                        let value_native_item_native_key = value_native_item.key;
                        let value_native_item_native_ready = value_native_item.ready;
                        let value_native_item_native_error = value_native_item.error;
                        let value_native_item_native = PollEvent {
                            key: value_native_item_native_key,
                            ready: value_native_item_native_ready,
                            error: value_native_item_native_error,
                        };
                        value_native_values.push(value_native_item_native);
                    }
                    let value_native = context.store_array(value_native_values);
                    unsafe {
                        std::ptr::write(out, value_native);
                    }
                    Ok(())
                }
                Err(error) => Err(RuntimeError::from(error).boxed()),
            }
        },
    )
}

