#[inline]
fn destack_io_completion_wait_vm_replay(
    runtime: &RuntimeCallContext,
    context: &mut vm::RuntimeContext<'_>,
    handle: resource::CompletionHandle,
    timeoutns: u64,
    maxevents: u32,
) -> RuntimeResult<vm::Value> {
    let result = runtime.replay().run_binding_with_context(
        COMPLETION_WAIT,
        context,
        |context| {
            platform_vm::destack_io_completion_wait(runtime, context, handle, timeoutns, maxevents)
        },
        |context, result| {
            let _ = &context;
            if let Ok(value) = result {
                let result_value = *value;
                let result_replay_raw = result_value.raw_values(context)?;
                let mut result_replay = Vec::with_capacity(result_replay_raw.len());
                for result_replay_item_value in result_replay_raw {
                    let result_replay_item = {
                        if result_replay_item_value.tag() != vm::ValueTag::Aggregate {
                            return Err(RuntimeError::from(PlatformError::invalid_argument_type(
                                "result_replay_item",
                                "item",
                            ))
                            .boxed());
                        }
                        let slots = context
                            .aggregate_slots(result_replay_item_value)
                            .map_err(|error| RuntimeError::from(error).boxed())?;
                        if slots.len() != 3 {
                            return Err(RuntimeError::from(PlatformError::invalid_argument_value(
                                "result_replay_item",
                                "expected 3 fields",
                            ))
                            .boxed());
                        }
                        let result_replay_item_key =
                            decode_uint64(slots[0], "result_replay_item_key", "key")?;
                        let result_replay_item_result =
                            decode_int64(slots[1], "result_replay_item_result", "result")?;
                        let result_replay_item_flags =
                            decode_uint32(slots[2], "result_replay_item_flags", "flags")?;
                        CompletionEventVm {
                            key: result_replay_item_key,
                            result: result_replay_item_result,
                            flags: result_replay_item_flags,
                        }
                    };
                    let result_replay_item_replay_key = result_replay_item.key;
                    let result_replay_item_replay_result = result_replay_item.result;
                    let result_replay_item_replay_flags = result_replay_item.flags;
                    let result_replay_item_replay = CompletionEvent {
                        key: result_replay_item_replay_key,
                        result: result_replay_item_replay_result,
                        flags: result_replay_item_replay_flags,
                    };
                    result_replay.push(result_replay_item_replay);
                }
                let payload = CompletionWaitReplay {
                    result: Ok(result_replay),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(PlatformError::from(error.as_ref()));
                    CompletionWaitReplay { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |context, payload| {
            let _ = &context;
            // replay result
            match payload.result {
                Ok(value) => {
                    let mut vm_result_values = Vec::with_capacity(value.len());
                    for vm_result_item in value.iter() {
                        let vm_result_item = *vm_result_item;
                        let vm_result_item_value_key = vm_result_item.key;
                        let vm_result_item_value_result = vm_result_item.result;
                        let vm_result_item_value_flags = vm_result_item.flags;
                        let vm_result_item_value = CompletionEventVm {
                            key: vm_result_item_value_key,
                            result: vm_result_item_value_result,
                            flags: vm_result_item_value_flags,
                        };
                        let vm_result_item_value_encoded = {
                            let field_0 = vm::Value::uint(vm_result_item_value.key, 64);
                            let field_1 = vm::Value::int(vm_result_item_value.result, 64);
                            let field_2 = vm::Value::uint(vm_result_item_value.flags as u64, 32);
                            context.allocate_aggregate(vec![field_0, field_1, field_2])
                        };
                        vm_result_values.push(vm_result_item_value_encoded);
                    }
                    let vm_result_data = context.allocate_raw_values(vm_result_values);
                    let vm_result: VmArray<CompletionEventVm> = VmArray {
                        data: vm_result_data,
                        len: value.len() as u32,
                        capacity: value.len() as u32,
                        _marker: std::marker::PhantomData,
                    };
                    Ok(vm_result)
                }
                Err(error) => Err(RuntimeError::from(error).boxed()),
            }
        },
    );
    let result = encode_destack_io_completion_wait_result(context, result)?;
    Ok(result)
}

